def source(self, request):
    """Pulls values off the request in the provided location
    :param request: The flask request object to parse arguments from
    """
    if isinstance(self.location, six.string_types):
        value = getattr(request, self.location, MultiDict())
        if callable(value):
            value = value()
        if value is not None:
            return value
    else:
        values = MultiDict()
        for l in self.location:
            value = getattr(request, l, None)
            if callable(value):
                value = value()
            if value is not None:
                values.update(value)
        return values

    return MultiDict()

def convert(self, value, op):
    # Don't cast None
    if value is None:
        if self.nullable:
            return None
        else:
            raise ValueError('Must not be null!')

    # and check if we're expecting a filestorage and haven't overridden `type`
    # (required because the below instantiation isn't valid for FileStorage)
    elif isinstance(value, FileStorage) and self.type == FileStorage:
        return value

    try:
        return self.type(value, self.name, op)
    except TypeError:
        try:
            if self.type is decimal.Decimal:
                return self.type(str(value))
            else:
                return self.type(value, self.name)
        except TypeError:
            return self.type(value)

